#!/usr/bin/env node
// floorplan/serve.mjs: serve this map locally and answer questions about the codebase through any
// supported AI engine: Claude Code, Codex, Antigravity, Kimi (CLI or Moonshot API), Gemini (CLI or API),
// OpenAI/OpenRouter-compatible HTTP endpoints, Ollama, Custom CLI, or the built-in 100% offline Local Engine.
// Generated by build.mjs; needs only Node 18+ (zero external npm dependencies).
//
// usage: node floorplan/serve.mjs [--port 4378] [--engine <id>] [--model <model>] [--cli-cmd "<cmd>"]
//                                 [--claude <path>] [--codex <path>] [--kimi <path>] [--gemini <path>] [--agy <path>]
//                                 [--editor <name or link>] [--auto-refresh] [--no-open] [--idle-exit <minutes>]
//        node floorplan/serve.mjs --stop
//        node floorplan/serve.mjs --export [<file>] [--include flows,notes,recent,health]

import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawn, execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { scriptJson, withPolicy, editorTemplate } from './page-safety.mjs';
// __ENGINES_HTTP_START__
import {
  loadUserEnginesConfig,
  safeReadSnippet,
  maskSnippetSecrets,
  parseUniversalAnswer,
  resolveHttpProvider,
  probeOllama,
  createReadOnlyTools,
  runHttpEngineQuery,
} from '../scripts/lib/engines-http.mjs';
// __ENGINES_HTTP_END__

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '..');
const argv = process.argv.slice(2);
const readJson = (file) => JSON.parse(fs.readFileSync(file, 'utf8').replace(/^\uFEFF/, ''));
const opt = (name, dflt) => { const i = argv.indexOf('--' + name); return i < 0 ? dflt : argv[i + 1]; };
const has = (name) => argv.includes('--' + name);
const stateFile = path.join(here, '.cache', 'server.json');
const readState = () => { try { return readJson(stateFile); } catch { return null; } };

if (has('stop')) {
  const s = readState();
  let stopped = false;
  if (s?.pid) { try { process.kill(s.pid); stopped = true; } catch {} }
  try { fs.unlinkSync(stateFile); } catch {}
  console.log(stopped ? `Stopped the map server (${s.url}).` : 'The map server was not running.');
  process.exit(0);
}

// Health issues marked "not a problem" on the map; build.mjs folds them into graph.json
const dismissedFile = path.join(here, 'health-dismissed.json');
const readDismissed = () => { try { const { dismissed } = readJson(dismissedFile); return Array.isArray(dismissed) ? dismissed : []; } catch { return []; } };
const cleanDismissal = (d) => ({
  id: String(d.id).slice(0, 2000),
  locations: (Array.isArray(d.locations) ? d.locations : []).slice(0, 500).map((l) => String(l).slice(0, 1000)),
  ...(d.severity ? { severity: String(d.severity).slice(0, 20) } : {}),
  ...(d.reason ? { reason: String(d.reason).slice(0, 1000) } : {}),
  at: new Date().toISOString(),
});

// ---------- export: a copy of the map to share ----------
const EXPORT_PARTS = ['flows', 'notes', 'recent', 'health'];
const EXPORT_DEFAULT = ['flows', 'notes'];
const DATA_START = '<script>window.FLOORPLAN = ';
function exportMap(include, extraFlows = []) {
  const html = fs.readFileSync(path.join(here, 'index.html'), 'utf8');
  const a = html.indexOf(DATA_START), b = html.indexOf(';</script>', a);
  if (a < 0 || b < 0) throw Object.assign(new Error('This map is too old to export. Update the floorplan first.'), { plain: true });
  const g = JSON.parse(html.slice(a + DATA_START.length, b));
  const on = EXPORT_PARTS.filter((p) => include.includes(p));
  const out = {
    ...g,
    meta: { ...g.meta, root: null, repos: (g.meta.repos || []).map(({ remote, ...r }) => r), exported: { at: new Date().toISOString(), include: on } },
    flows: on.includes('flows') ? [...g.flows, ...extraFlows.filter((f) => !g.flows.some((x) => x.id === f.id))] : [],
    tour: on.includes('flows') ? g.tour : [],
    files: on.includes('notes') ? g.files : g.files.map(({ note, ...f }) => f),
  };
  if (!on.includes('recent')) delete out.recent;
  if (!on.includes('health')) delete out.health;
  else if (out.health) { const list = readDismissed().map(({ reason, ...d }) => d); if (list.length) out.health = { ...out.health, dismissed: list }; else delete out.health.dismissed; }
  const json = scriptJson(out);
  const slug = String(g.project?.name || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'floorplan';
  return { html: withPolicy(html.slice(0, a + DATA_START.length) + json + html.slice(b), 'export'), name: `${slug}-map.html`, include: on, plan: !!g.meta?.blueprint };
}

const cleanFlows = (list) => (Array.isArray(list) ? list : []).slice(0, 50)
  .filter((f) => f && typeof f.id === 'string' && Array.isArray(f.steps))
  .map((f) => ({
    id: f.id.slice(0, 100), title: String(f.title || 'Flow').slice(0, 200), description: String(f.description || '').slice(0, 1000), custom: true,
    steps: f.steps.slice(0, 60).filter((s) => s && typeof s.ref === 'string').map((s) => ({ ref: s.ref.slice(0, 300), note: String(s.note || '').slice(0, 2000) })),
  }))
  .filter((f) => f.steps.length >= 2);

if (has('export')) {
  const dest = opt('export');
  const include = String(opt('include', EXPORT_DEFAULT.join(','))).split(',').map((s) => s.trim().toLowerCase());
  try {
    const x = exportMap(include);
    const file = path.resolve(dest && !dest.startsWith('--') ? dest : path.join(here, x.name));
    fs.writeFileSync(file, x.html);
    console.log(`Exported the map to ${file}`);
    const label = { flows: 'flows and the tour', notes: 'notes', recent: 'recent work', health: x.plan ? 'the design review' : 'the health check' };
    console.log(`Includes: the map${x.include.map((p) => ', ' + label[p]).join('')}. One file that opens in any browser, with no Ask bar.`);
    if (x.include.includes('health') && !x.plan) console.log('It includes the health check: which endpoints are open and where secrets sit in the code (never their values). Share it only with people you trust.');
    process.exit(0);
  } catch (e) { console.error(`✗ Couldn't export the map: ${e.message}`); process.exit(1); }
}

const wantPort = Number(opt('port', 4378));
const idleExit = Number(opt('idle-exit', 0)) * 60000;
const autoRefresh = has('auto-refresh') || /^(1|true|yes)$/i.test(process.env.FLOORPLAN_AUTO_REFRESH || '');
const autoRefreshMs = Math.max(800, Number(opt('auto-refresh-ms', process.env.FLOORPLAN_AUTO_REFRESH_MS || 3500)) || 3500);
const selfHash = crypto.createHash('sha1').update(fs.readFileSync(fileURLToPath(import.meta.url))).digest('hex').slice(0, 12);
let model = opt('model', process.env.FLOORPLAN_MODEL || '');
const editorSetting = editorTemplate(opt('editor', process.env.FLOORPLAN_EDITOR || ''));
if (editorSetting.error) { console.error(`✗ ${has('editor') ? '--editor' : 'FLOORPLAN_EDITOR'} ${editorSetting.error}`); process.exit(1); }
const editor = editorSetting.template;
const token = crypto.randomBytes(16).toString('hex');
const TYPES = { '.html': 'text/html; charset=utf-8', '.json': 'application/json', '.js': 'text/javascript', '.mjs': 'text/javascript', '.css': 'text/css', '.svg': 'image/svg+xml' };

// ---------- Universal Engine Registry (CLI + HTTP + Local) ----------
function which(cmd) {
  try {
    const out = execFileSync(process.platform === 'win32' ? 'where' : 'which', [cmd], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'], windowsHide: true });
    return out.split(/\r?\n/).map((s) => s.trim()).filter(Boolean);
  } catch { return []; }
}

function resolveCli(candidates, npmEntry = []) {
  for (const c of candidates) {
    if (!c || !fs.existsSync(c)) continue;
    if (/\.(m?js)$/i.test(c)) return { cmd: process.execPath, args: [c], path: c };
    if (/\.(cmd|bat|ps1)$/i.test(c) || (process.platform === 'win32' && !path.extname(c))) {
      if (npmEntry.length) {
        const cliJs = path.join(path.dirname(c), 'node_modules', ...npmEntry);
        if (fs.existsSync(cliJs)) return { cmd: process.execPath, args: [cliJs], path: c };
        const pkgExe = path.join(path.dirname(c), 'node_modules', ...npmEntry.slice(0, 2), 'bin', path.basename(c).replace(/\.[^.]*$/, '') + '.exe');
        if (fs.existsSync(pkgExe)) return { cmd: pkgExe, args: [], path: pkgExe };
      }
      const exe = c.replace(/\.(cmd|bat|ps1)$/i, '.exe');
      if (exe !== c && fs.existsSync(exe)) return { cmd: exe, args: [], path: exe };
      if (process.platform === 'win32' && /\.(cmd|bat)$/i.test(c)) return { cmd: 'cmd.exe', args: ['/d', '/s', '/c', c], path: c };
      continue;
    }
    return { cmd: c, args: [], path: c };
  }
  return null;
}

const HOME = process.env.HOME || process.env.USERPROFILE || '';
const given = (name) => { const p = opt(name, process.env['FLOORPLAN_' + name.toUpperCase()]); return p ? [p] : null; };

function codexApp() {
  if (process.platform === 'darwin') return ['/Applications/Codex.app/Contents/Resources/codex'];
  if (process.platform !== 'win32') return [];
  const base = path.join(process.env.LOCALAPPDATA || '', 'OpenAI', 'Codex', 'bin');
  try {
    return fs.readdirSync(base).map((d) => path.join(base, d, 'codex.exe')).filter((f) => fs.existsSync(f))
      .sort((a, b) => fs.statSync(b).mtimeMs - fs.statSync(a).mtimeMs);
  } catch { return []; }
}

function splitShellWords(cmdStr) {
  const words = [];
  for (const m of String(cmdStr || '').matchAll(/"([^"]*)"|'([^']*)'|(\S+)/g)) {
    words.push(m[1] ?? m[2] ?? m[3]);
  }
  return words;
}

function resolveCustomCli() {
  const userCfg = loadUserEnginesConfig();
  const raw = opt('cli-cmd', process.env.FLOORPLAN_CLI_CMD || userCfg['custom-cli']?.cmd || '');
  if (!raw) return null;
  const parts = splitShellWords(raw);
  if (!parts.length) return null;
  const found = fs.existsSync(parts[0]) ? parts[0] : which(parts[0])[0];
  if (!found) return null;
  const resolved = resolveCli([found]);
  if (!resolved) return null;
  return { cmd: resolved.cmd, args: [...resolved.args, ...parts.slice(1)], path: resolved.path, raw };
}

function cliEnv() {
  const env = { ...process.env };
  for (const k of Object.keys(env)) {
    if (/^CLAUDE_?CODE_(SESSION|ENTRYPOINT|CHILD|MESSAGING|HOST|SDK)|^CLAUDECODE$|^CODEX_(THREAD_ID|SESSION_ID|TOOL_CALL_ID|CI$|SANDBOX)|^ANTIGRAVITY_SESSION_ID$/.test(k)) delete env[k];
  }
  return env;
}

let ollamaCache = { at: 0, probe: null };
async function getOllamaStatus() {
  if (Date.now() - ollamaCache.at < 15000 && ollamaCache.probe) return ollamaCache.probe;
  const prov = resolveHttpProvider('ollama', { modelOverride: model });
  const probe = await probeOllama(prov.hostUrl, 550);
  ollamaCache = { at: Date.now(), probe: { prov, ...probe } };
  return ollamaCache.probe;
}

const ENGINES = {
  claude: {
    id: 'claude', label: 'Claude Code', name: 'Claude Code CLI', site: 'https://docs.claude.com/en/docs/claude-code',
    protocol: 'cli', structured: true,
    find: () => resolveCli(given('claude') || [
      ...which('claude'),
      path.join(HOME, '.local', 'bin', process.platform === 'win32' ? 'claude.exe' : 'claude'),
      ...(process.platform === 'win32' ? [path.join(process.env.APPDATA || '', 'npm', 'claude.cmd')] : []),
    ], ['@anthropic-ai', 'claude-code', 'cli.js']),
    run: claudeRun,
  },
  codex: {
    id: 'codex', label: 'Codex', name: 'Codex', site: 'https://developers.openai.com/codex',
    protocol: 'cli', structured: true, schemaFile: true,
    find: () => resolveCli(given('codex') || [...which('codex'), ...codexApp()], ['@openai', 'codex', 'bin', 'codex.js']),
    run: codexRun,
  },
  kimi: {
    id: 'kimi', label: 'Kimi', name: 'Kimi (Moonshot AI)', site: 'https://platform.moonshot.ai/docs',
    protocol: 'hybrid', structured: true,
    find: () => {
      const httpProv = resolveHttpProvider('kimi', { modelOverride: model });
      if (httpProv.available) return { protocol: 'http', provider: httpProv, path: httpProv.baseUrl };
      const bin = resolveCli(given('kimi') || which('kimi'));
      return bin ? { ...bin, protocol: 'cli' } : null;
    },
    run: genericCliRun,
  },
  gemini: {
    id: 'gemini', label: 'Gemini', name: 'Gemini CLI / API', site: 'https://ai.google.dev/gemini-api/docs',
    protocol: 'hybrid', structured: true,
    find: () => {
      const httpProv = resolveHttpProvider('gemini', { modelOverride: model });
      if (httpProv.available) return { protocol: 'http', provider: httpProv, path: httpProv.baseUrl };
      const bin = resolveCli(given('gemini') || [
        ...which('gemini'),
        ...(process.platform === 'win32' ? [path.join(process.env.APPDATA || '', 'npm', 'gemini.cmd')] : []),
      ], ['@google', 'gemini-cli', 'dist', 'index.js']);
      return bin ? { ...bin, protocol: 'cli' } : null;
    },
    run: geminiCliRun,
  },
  antigravity: {
    id: 'antigravity', label: 'Antigravity', name: 'Google Antigravity CLI', site: 'https://antigravity.google/docs',
    protocol: 'cli', structured: false,
    find: () => resolveCli(given('agy') || given('antigravity') || which('agy')),
    run: genericCliRun,
  },
  'openai-http': {
    id: 'openai-http', label: 'OpenAI / OpenRouter', name: 'OpenAI-Compatible HTTP API', site: 'https://openrouter.ai/docs',
    protocol: 'http', structured: true,
    find: () => {
      const prov = resolveHttpProvider('openai-http', { modelOverride: model });
      return prov.available ? { protocol: 'http', provider: prov, path: prov.baseUrl } : null;
    },
    run: null,
  },
  ollama: {
    id: 'ollama', label: 'Ollama', name: 'Ollama (Local LLM)', site: 'https://ollama.com',
    protocol: 'http', structured: true,
    find: () => {
      const prov = resolveHttpProvider('ollama', { modelOverride: model });
      if (prov.available || ollamaCache.probe?.ok) {
        const chosenModel = model || process.env.OLLAMA_MODEL || ollamaCache.probe?.models?.[0] || prov.model;
        return { protocol: 'http', provider: { ...prov, available: true, model: chosenModel }, path: prov.hostUrl };
      }
      return null;
    },
    run: null,
  },
  'custom-cli': {
    id: 'custom-cli', label: 'Custom CLI', name: 'Custom AI CLI', site: '',
    protocol: 'cli', structured: false,
    find: () => resolveCustomCli(),
    run: genericCliRun,
  },
  local: {
    id: 'local', label: 'Local Engine', name: 'Floorplan Local Graph & Code Engine', site: '',
    protocol: 'local', structured: false,
    find: () => ({ protocol: 'local', cmd: process.execPath, args: [], path: 'built-in offline engine' }),
    run: null,
  },
};

const ALIAS_TO_ENGINE = {
  agy: 'antigravity', 'google-antigravity': 'antigravity',
  'claude-code': 'claude', anthropic: 'claude',
  'openai-codex': 'codex',
  moonshot: 'kimi', 'kimi-cli': 'kimi', 'kimi-http': 'kimi',
  'gemini-cli': 'gemini', 'gemini-http': 'gemini',
  openai: 'openai-http', openrouter: 'openai-http', deepseek: 'openai-http', vllm: 'openai-http',
  'ollama-local': 'ollama',
  custom: 'custom-cli',
  offline: 'local', builtin: 'local',
};
const normEngine = (k) => {
  const s = String(k || '').trim().toLowerCase();
  if (Object.hasOwn(ENGINES, s)) return s;
  return ALIAS_TO_ENGINE[s] || null;
};
const isEngine = (k) => !!normEngine(k);

const userCfgInit = loadUserEnginesConfig();
const builtBy = (() => { try { return normEngine(readJson(path.join(here, 'graph.json')).meta?.agent); } catch { return null; } })();
const asked = normEngine(opt('engine', process.env.FLOORPLAN_ENGINE || userCfgInit.defaultEngine || ''));
// Priority order: requested -> agent that built the map -> external configured/installed engines -> always-available 'local'
const AUTO_ORDER = ['kimi', 'claude', 'codex', 'gemini', 'openai-http', 'ollama', 'custom-cli', 'antigravity', 'local'];
const want = asked || builtBy || 'local';
let engine = 'local', cli = ENGINES.local.find();
const candidatesOrder = asked
  ? [asked, 'local']
  : [...new Set([ ...(builtBy && builtBy !== 'local' ? [builtBy] : []), ...AUTO_ORDER ])];
for (const k of candidatesOrder) {
  const found = ENGINES[k]?.find();
  if (found) { engine = k; cli = found; break; }
}

let version = null;
function refreshVersion() {
  version = null;
  if (cli && cli.protocol !== 'http' && cli.protocol !== 'local' && cli.cmd) {
    try { version = execFileSync(cli.cmd, [...cli.args, '--version'], { encoding: 'utf8', timeout: 8000, stdio: ['ignore', 'pipe', 'ignore'], windowsHide: true }).trim().split(/\r?\n/)[0]; } catch {}
  } else if (cli?.provider) {
    version = cli.provider.model;
  }
}
refreshVersion();

function activeProtocol(engId = engine, resolved = cli) {
  return resolved?.protocol || ENGINES[engId]?.protocol || 'local';
}

async function listAvailableEngines() {
  await getOllamaStatus();
  return Object.values(ENGINES).map((e) => {
    const found = e.find();
    const proto = found?.protocol || (e.protocol === 'hybrid' ? 'http' : e.protocol);
    return {
      id: e.id,
      label: found?.provider?.label || e.label,
      name: e.name,
      protocol: proto,
      available: !!found,
      structured: !!e.structured,
      model: found?.provider?.model || (e.id === engine ? model || null : null),
      detail: found?.provider?.detail || (e.id === 'local' ? '100% Offline Graph + Code' : found?.path ? path.basename(found.path) : 'not configured'),
    };
  });
}

let page, G, core, MODES;
function buildServerPayload() {
  const canChange = !!(ENGINES[engine]?.structured && cli);
  return {
    token,
    cli: !!cli,
    engine,
    engineLabel: cli?.provider?.label || ENGINES[engine]?.label || engine,
    protocol: activeProtocol(),
    want,
    version,
    model: model || cli?.provider?.model || null,
    change: canChange,
    editor,
    autoRefresh,
  };
}

function load() {
  const html = fs.readFileSync(path.join(here, 'index.html'), 'utf8');
  const g = readJson(path.join(here, 'graph.json'));
  const coreSrc = fs.readFileSync(path.join(here, 'query.mjs'), 'utf8').split('// ---- cli ----')[0];
  const c = new Function(`${coreSrc.replace(/^import .*$/gm, '')}; return { FLOORPLAN_ANSWER_SCHEMA, FLOORPLAN_FLOW_SCHEMA, FLOORPLAN_CHANGE_SCHEMA, floorplanAskInstructions, floorplanFlowInstructions, floorplanChangeInstructions, createGraphQuery };`)();
  c.q = c.createGraphQuery(g);
  const inject = `<script>window.FLOORPLAN_SERVER=${scriptJson(buildServerPayload())};</script>`;
  page = withPolicy(html.replace('</head>', inject + '</head>'), 'local');
  G = g; core = c;
  const canChange = !!(ENGINES[engine]?.structured && cli);
  MODES = {
    ask: {
      instructions: core.floorplanAskInstructions(G, 'cli'),
      httpInstructions: core.floorplanAskInstructions(G, 'http'),
      schema: core.FLOORPLAN_ANSWER_SCHEMA,
      file: path.join(here, '.cache', 'answer-schema.json'),
    },
    flow: {
      instructions: core.floorplanFlowInstructions(G, 'cli'),
      httpInstructions: core.floorplanFlowInstructions(G, 'http'),
      schema: core.FLOORPLAN_FLOW_SCHEMA,
      file: path.join(here, '.cache', 'flow-schema.json'),
    },
    ...(G.meta?.blueprint && canChange ? {
      change: {
        instructions: core.floorplanChangeInstructions(G),
        httpInstructions: core.floorplanChangeInstructions(G),
        schema: core.FLOORPLAN_CHANGE_SCHEMA,
        file: path.join(here, '.cache', 'change-schema.json'),
      },
    } : {}),
  };
  if (ENGINES[engine]?.schemaFile) {
    fs.mkdirSync(path.join(here, '.cache'), { recursive: true });
    for (const m of Object.values(MODES)) fs.writeFileSync(m.file, JSON.stringify(strict(m.schema)));
  }
}

function strict(s) {
  if (s?.type === 'object' && s.properties) return { ...s, properties: Object.fromEntries(Object.entries(s.properties).map(([k, v]) => [k, strict(v)])), required: Object.keys(s.properties), additionalProperties: false };
  if (s?.type === 'array') return { ...s, items: strict(s.items) };
  return s;
}
load();

// ---------- open tabs: live reload, and idle shutdown ----------
const tabs = new Set();
let lastTab = Date.now();
const broadcast = (event, data = {}) => { for (const t of tabs) t.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`); };
let reloadTimer = null;
function scheduleReloadBroadcast(reason = 'map rebuilt: reloaded open tabs') {
  clearTimeout(reloadTimer);
  reloadTimer = setTimeout(() => {
    try { load(); broadcast('reload'); console.log(reason); } catch {}
  }, 500);
}
fs.watchFile(path.join(here, 'index.html'), { interval: 1000 }, (cur, prev) => {
  if (cur.mtimeMs === prev.mtimeMs) return;
  scheduleReloadBroadcast('map rebuilt: reloaded open tabs');
});

// ---------- optional zero-drift auto-refresh watcher (--auto-refresh) ----------
const WATCH_SKIP_DIRS = new Set(['.git', 'node_modules', '.next', 'dist', 'build', 'out', 'coverage', '.venv', 'venv', '__pycache__', 'target', 'vendor', '.turbo', '.cache']);
const WATCH_EXTS = new Set(['.js', '.mjs', '.cjs', '.ts', '.tsx', '.jsx', '.py', '.go', '.rs', '.java', '.kt', '.cs', '.rb', '.php', '.swift', '.vue', '.svelte', '.sql', '.graphql', '.prisma', '.yaml', '.yml', '.toml', '.json']);
function computeSourceFingerprint() {
  const entries = [];
  const hereResolved = path.resolve(here);
  const walk = (dir, depth) => {
    if (depth > 8 || entries.length >= 8000) return;
    let list;
    try { list = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
    for (const d of list) {
      if (entries.length >= 8000) break;
      const full = path.join(dir, d.name);
      if (d.isDirectory()) {
        if (WATCH_SKIP_DIRS.has(d.name) || path.resolve(full) === hereResolved) continue;
        walk(full, depth + 1);
      } else if (d.isFile() && WATCH_EXTS.has(path.extname(d.name).toLowerCase())) {
        try {
          const st = fs.statSync(full);
          entries.push(`${path.relative(root, full).replace(/\\/g, '/')}:${st.size}:${Math.floor(st.mtimeMs)}`);
        } catch {}
      }
    }
  };
  walk(root, 0);
  for (const cfg of ['architecture.json', 'plan.json']) {
    const fp = path.join(here, cfg);
    if (fs.existsSync(fp)) {
      try {
        const st = fs.statSync(fp);
        entries.push(`floorplan/${cfg}:${st.size}:${Math.floor(st.mtimeMs)}`);
      } catch {}
    }
  }
  entries.sort();
  return crypto.createHash('sha1').update(entries.join('\n')).digest('hex');
}

if (autoRefresh) {
  let lastFp = computeSourceFingerprint();
  let refreshing = false;
  setInterval(() => {
    if (refreshing || changing) return;
    const nextFp = computeSourceFingerprint();
    if (!nextFp || nextFp === lastFp) return;
    let skillDir = null;
    try { skillDir = readJson(path.join(here, '.cache', 'skill.json')).dir; } catch {}
    const refreshScript = skillDir ? path.join(skillDir, 'scripts', 'refresh.mjs') : null;
    if (!refreshScript || !fs.existsSync(refreshScript)) {
      lastFp = nextFp;
      return;
    }
    refreshing = true;
    lastFp = nextFp;
    const child = spawn(process.execPath, [refreshScript, root, '--json', '--no-agent-notes'], {
      cwd: root,
      stdio: ['ignore', 'pipe', 'pipe'],
      windowsHide: true,
    });
    child.on('close', (code) => {
      refreshing = false;
      lastFp = computeSourceFingerprint();
      if (code === 0) {
        scheduleReloadBroadcast('auto-refresh: source changed, rebuilt map & reloaded open tabs');
      }
    });
    child.on('error', () => { refreshing = false; });
  }, autoRefreshMs).unref();
}
if (idleExit) setInterval(() => { if (!tabs.size && !running.size && Date.now() - lastTab > idleExit) process.exit(0); }, 60000).unref();
