// ---------- asking ----------
const nameFor = (id) => { try { return core.q.brief(id)?.name || id; } catch { return id; } };
const running = new Map();
const rel = (p) => String(p || '').replace(/\\/g, '/').replace(root.replace(/\\/g, '/') + '/', '');

function describeCommand(command) {
  let c = String(command || '');
  const wrapped = /\s-(?:l?c|Command)\s+(["'])([\s\S]*)\1\s*$/i.exec(c);
  if (wrapped) c = wrapped[2].replace(/\\(["'])/g, '$1');
  const cmds = c.split(/\s*(?:&&|;|\|\|?)\s*/).filter(Boolean);
  const parts = cmds.map((x) => /query\.mjs\s+(\w+)\s*(.*)$/.exec(x)).filter(Boolean);
  if (parts.length) {
    const one = ([, cmd, rest]) => {
      const a = rest.replace(/--\w+\s+\S+/g, '').replace(/["']/g, '').trim();
      return { overview: 'Reading the map overview', find: a ? `Searching the map for "${a}"` : 'Searching the map', show: `Looking at ${a.split(/\s+/).map(nameFor).join(', ')}`, path: `Tracing a path ${a.split(/\s+/).map(nameFor).join(' → ')}` }[cmd] || 'Querying the map';
    };
    return parts.slice(0, 2).map(one).join(' · ') + (parts.length > 2 ? ` (+${parts.length - 2} more)` : '');
  }
  const first = cmds[0] || '';
  if (/^(rg|grep|git grep|Select-String|findstr)\b/i.test(first) && !/\s--files\b/.test(first)) {
    const pat = /\s(["'])(.+?)\1/.exec(first)?.[2] || /\s(?:-Pattern\s+)?([^\s-][^\s]*)/i.exec(first.replace(/^\S+(\s+-\S+)*/, ''))?.[1];
    return pat ? `Searching code for "${pat}"` : 'Searching code';
  }
  if (/^(rg\s.*--files|ls|dir|Get-ChildItem|gci|find|tree)\b/i.test(first)) return 'Listing files';
  if (/^(cat|type|Get-Content|gc|sed|head|tail|nl|more|less)\b/i.test(first)) {
    const file = [...first.matchAll(/[\w@.\\/-]+\.\w{1,6}\b/g)].map((m) => m[0]).pop();
    return file ? `Reading ${rel(file)}` : 'Reading a file';
  }
  return 'Running a command';
}

function describeTool(name, input = {}) {
  if (name === 'Bash') return describeCommand(input.command);
  if (name === 'Read') return /[\\/]tool-results[\\/]/.test(input.file_path || '') ? 'Reading the rest of a long file' : `Reading ${rel(input.file_path)}`;
  if (name === 'Grep') return `Searching code for "${input.pattern}"`;
  if (name === 'Glob') return `Listing ${input.pattern}`;
  return name;
}

const failCode = (msg) => /not logged in|logged out|\/login|log ?in again|sign in|authenticat|unauthori[sz]ed|invalid[ _-]?api[ _-]?key|\b401\b/i.test(msg) ? 'not_logged_in'
  : /usage limit|rate limit|too many requests|quota|\b429\b/i.test(msg) ? 'rate_limited' : 'cli_error';

function personaSuffix(body) {
  const tags = [];
  const wantAr = body.lang === 'ar' || /[\u0600-\u06FF]/.test(String(body.question || '')) || (!body.lang && G.meta?.language === 'ar');
  if (wantAr) tags.push('مهم جداً: اكتب جميع الحقول النصية في رد JSON (title, answer, description, items[].note, steps[].note, followups) باللغة العربية الفصحى السليمة والواضحة 100% حتى لو كانت أوصاف الخريطة بالإنجليزية.');
  if (body.audience === 'business') tags.push('وضع البيزنس المبسط: اشرح بلغة الأعمال التنفيذية المبسطة لغير التقنيين (رحلة المستفيد، قواعد العمل، القيمة الوظيفية، والجهات المتكاملة) وتجنب تماماً ذكر مسارات الملفات أو أرقام الأسطر أو أسماء الدوال أو الأكواد البرمجية.');
  return tags.length ? `\n\n[${tags.join(' ')}]` : '';
}

function modeForRequest(body) {
  const base = MODES[body.mode] || MODES.ask;
  if (!base || body.mode === 'change') return base;
  const wantAr = body.lang === 'ar' || /[\u0600-\u06FF]/.test(String(body.question || '')) || (!body.lang && G.meta?.language === 'ar');
  const reqLang = wantAr ? 'ar' : (body.lang === 'en' ? 'en' : undefined);
  const reqAudience = body.audience === 'business' ? 'business' : 'technical';
  const opts = { lang: reqLang, audience: reqAudience };
  const isFlow = body.mode === 'flow';
  return {
    ...base,
    instructions: isFlow ? core.floorplanFlowInstructions(G, 'cli', opts) : core.floorplanAskInstructions(G, 'cli', opts),
    httpInstructions: isFlow ? core.floorplanFlowInstructions(G, 'http', opts) : core.floorplanAskInstructions(G, 'http', opts),
  };
}

function claudeRun(activeCli, body, mode) {
  const args = [...activeCli.args, '-p', '--output-format', 'stream-json', '--verbose',
    '--json-schema', JSON.stringify(mode.schema), '--append-system-prompt', mode.instructions,
    '--disallowedTools', 'Read(floorplan/index.html)', 'Read(floorplan/serve.mjs)', 'Read(floorplan/page-safety.mjs)', 'Read(floorplan/.cache/**)',
    '--strict-mcp-config', '--mcp-config', '{"mcpServers":{}}',
    '--tools', 'Read,Grep,Glob,Bash', '--allowedTools', 'Bash(node floorplan/query.mjs:*)', 'Read', 'Grep', 'Glob'];
  if (body.session) args.push('--resume', String(body.session));
  if (model) args.push('--model', model);
  return {
    streamJson: true,
    args,
    input: String(body.question || '').slice(0, 4000) + personaSuffix(body),
    onEvent(ev, out) {
      if (ev.type === 'assistant') for (const c of ev.message?.content || []) if (c.type === 'tool_use') out.progress(describeTool(c.name, c.input));
      if (ev.type !== 'result') return;
      if (ev.is_error) out.fail(String(ev.result || ev.subtype || 'Claude Code reported an error'));
      else out.answer({ ...parseUniversalAnswer(ev, core.q, body.question), session: ev.session_id });
    },
  };
}

const convos = new Map();
function codexRun(activeCli, body, mode) {
  const session = convos.has(body.session) ? body.session : crypto.randomBytes(8).toString('hex');
  const turns = convos.get(session) || [];
  const question = String(body.question || '').slice(0, 4000);
  const earlier = turns.length ? `\n\nEarlier in this conversation:\n${turns.map((t) => `Q: ${t.q}\nA: ${t.a}`).join('\n\n')}` : '';
  fs.mkdirSync(path.join(here, '.cache'), { recursive: true });
  if (mode.file && !fs.existsSync(mode.file)) fs.writeFileSync(mode.file, JSON.stringify(strict(mode.schema)));
  const args = [...activeCli.args, 'exec', '--json', '--sandbox', 'read-only', '--skip-git-repo-check', '--ephemeral',
    '--output-schema', mode.file, '-C', root];
  if (model) args.push('--model', model);
  args.push('-');
  let last = '', error = '';
  return {
    streamJson: true,
    args,
    input: `${mode.instructions}${earlier}\n\nThe question:\n${question}`,
    onEvent(ev, out) {
      if (ev.type === 'item.started' && ev.item?.type === 'command_execution') out.progress(describeCommand(ev.item.command));
      if (ev.type === 'item.completed' && ev.item?.type === 'agent_message') last = String(ev.item.text || '');
      if (ev.type === 'error') error = String(ev.message || error);
      if (ev.type === 'turn.failed') out.fail(String(ev.error?.message || error || 'Codex reported an error'));
      if (ev.type === 'turn.completed') {
        const a = parseUniversalAnswer(last, core.q, question);
        convos.set(session, [...turns, { q: question.slice(0, 500), a: String(a.answer || '').slice(0, 1500) }].slice(-4));
        out.answer({ ...a, session });
      }
    },
    lastError: () => error,
  };
}

function geminiCliRun(activeCli, body, mode) {
  const session = convos.has(body.session) ? body.session : crypto.randomBytes(8).toString('hex');
  const turns = convos.get(session) || [];
  const question = String(body.question || '').slice(0, 4000);
  const earlier = turns.length ? `\n\nEarlier in this conversation:\n${turns.map((t) => `Q: ${t.q}\nA: ${t.a}`).join('\n\n')}` : '';
  const prompt = `${mode.instructions}\nRequired JSON Schema:\n${JSON.stringify(mode.schema)}${earlier}\n\nQuestion:\n${question}`;
  const args = [...activeCli.args, '-p', prompt];
  if (model) args.push('-m', model);
  return {
    streamJson: false,
    args,
    input: '',
    session,
    turns,
    question,
  };
}

function genericCliRun(activeCli, body, mode) {
  const session = convos.has(body.session) ? body.session : crypto.randomBytes(8).toString('hex');
  const turns = convos.get(session) || [];
  const question = String(body.question || '').slice(0, 4000);
  const earlier = turns.length ? `\n\nEarlier in this conversation:\n${turns.map((t) => `Q: ${t.q}\nA: ${t.a}`).join('\n\n')}` : '';
  const fullPrompt = `${mode.instructions}\nRequired JSON Schema:\n${JSON.stringify(mode.schema)}${earlier}\n\nQuestion:\n${question}`;
  const args = [...activeCli.args];
  let input = fullPrompt;
  // If CLI args end with -p or --prompt, pass prompt as the next CLI argument
  if (args.length && /^(-p|--prompt)$/i.test(args[args.length - 1])) {
    args.push(fullPrompt);
    input = '';
  }
  return {
    streamJson: false,
    args,
    input,
    session,
    turns,
    question,
  };
}

const CLOSED = Symbol('closed');

function runAgent(res, send, body, chosenId = engine) {
  const engDef = ENGINES[chosenId] || ENGINES.local;
  const activeCli = chosenId === engine ? cli : engDef.find();
  const modeObj = modeForRequest(body);
  const augmentedBody = body.mode === 'change' ? body : { ...body, question: String(body.question || '').slice(0, 4000) + personaSuffix(body) };

  if (!activeCli) return Promise.reject(new Error(`${engDef.name} is not available.`));

  // HTTP Protocol Adapter (Kimi Moonshot, Gemini API, OpenAI/OpenRouter, Ollama)
  if (activeCli.protocol === 'http' && activeCli.provider) {
    return new Promise((resolve, reject) => {
      const id = crypto.randomBytes(6).toString('hex');
      const ac = new AbortController();
      running.set(id, { kill: () => ac.abort() });
      send('start', { id });
      const session = convos.has(body.session) ? body.session : crypto.randomBytes(8).toString('hex');
      const turns = convos.get(session) || [];
      const question = augmentedBody.question;
      let said = '';
      const onProgress = (text) => { if (text && text !== said) { said = text; send('progress', { text }); } };
      res.on('close', () => { ac.abort(); running.delete(id); reject(CLOSED); });
      runHttpEngineQuery({
        provider: model ? { ...activeCli.provider, model } : activeCli.provider,
        root,
        q: core.q,
        modeObj,
        question,
        history: turns,
        onProgress,
        signal: ac.signal,
      }).then((ans) => {
        running.delete(id);
        convos.set(session, [...turns, { q: String(body.question || '').slice(0, 500), a: String(ans.answer || '').slice(0, 1500) }].slice(-4));
        resolve({ ...ans, session });
      }, (err) => {
        running.delete(id);
        if (ac.signal.aborted) reject(CLOSED);
        else reject(err);
      });
    });
  }

  // CLI Protocol Adapter (Claude, Codex, Kimi CLI, Gemini CLI, Antigravity CLI, Custom CLI)
  return new Promise((resolve, reject) => {
    const run = engDef.run(activeCli, chosenId === 'claude' ? body : augmentedBody, modeObj);
    const child = spawn(activeCli.cmd, run.args, { cwd: root, env: cliEnv(), stdio: ['pipe', 'pipe', 'pipe'], windowsHide: true });
    const id = crypto.randomBytes(6).toString('hex');
    running.set(id, child);
    send('start', { id });
    if (run.input) child.stdin.end(run.input); else child.stdin.end();
    let buf = '', rawStdout = '', stderr = '', done = false;
    let quiet = null, said = '';
    const say = (text) => { if (!done && text !== said) { said = text; send('progress', { text }); } };
    const hush = () => { clearTimeout(quiet); if (body.mode === 'change' && !done) quiet = setTimeout(() => say('Working on the updated plan'), 12000); };
    const out = {
      progress: (text) => { if (!done) { say(text); hush(); } },
      answer: (data) => { if (!done) { done = true; clearTimeout(quiet); resolve(data); } },
      fail: (message) => { if (!done) { done = true; clearTimeout(quiet); reject(new Error(message)); } },
    };
    say(`Running ${engDef.label}…`);
    hush();
    child.stdout.on('data', (d) => {
      rawStdout += d;
      if (!run.streamJson) return;
      buf += d;
      let nl;
      while ((nl = buf.indexOf('\n')) >= 0) {
        const line = buf.slice(0, nl).trim(); buf = buf.slice(nl + 1);
        if (!line) continue;
        let ev; try { ev = JSON.parse(line); } catch { continue; }
        run.onEvent(ev, out);
      }
    });
    child.stderr.on('data', (d) => { stderr = (stderr + d).slice(-2000); });
    child.on('error', (e) => out.fail(e.message));
    child.on('close', (code) => {
      running.delete(id);
      if (done) return;
      if (!run.streamJson && code === 0 && rawStdout.trim()) {
        const parsed = parseUniversalAnswer(rawStdout, core.q, run.question);
        if (run.session) {
          convos.set(run.session, [...(run.turns || []), { q: (run.question || '').slice(0, 500), a: String(parsed.answer || '').slice(0, 1500) }].slice(-4));
        }
        out.answer({ ...parsed, ...(run.session ? { session: run.session } : {}) });
        return;
      }
      out.fail(run.lastError?.() || stderr.trim() || `${engDef.label} exited with code ${code}`);
    });
    res.on('close', () => { if (!done) { done = true; clearTimeout(quiet); child.kill(); reject(CLOSED); } });
  });
}

// ---------- Universal Bilingual Local Graph + Code Engine ----------
const UNIVERSAL_AR_SYNONYMS = [
  [/تسجيل\s*الدخول|دخول|لوجن|مصادق[ةه]|هوي[ةه]|توكن/g, 'login auth signin callback oauth oidc jwt token session'],
  [/خروج|تسجيل\s*الخروج/g, 'logout signout session cookie clear revoke'],
  [/جلس[ةه]|خمول|تايم\s*اوت|انتهاء|تمديد/g, 'session idle timeout keepalive refresh expire'],
  [/صلاحي[ةه]|صلاحيات|أدوار|دور|حارس|حماي[ةه]/g, 'permission role rbac authorize guard middleware policy'],
  [/دفع|مدفوعات|فاتور[ةه]|فواتير|اشتراك|استرداد/g, 'payment billing invoice checkout charge refund webhook'],
  [/مستخدم|مستخدمين|حساب|ملف\s*شخصي|بروفايل/g, 'user users account profile settings preferences'],
  [/بريد|ايميل|إيميل|اشعار|إشعار|رسائل|تنبيه/g, 'email mail notification message sms webhook sender'],
  [/رمز|تحقق|تأكيد|باسورد|كلم[ةه]\s*المرور/g, 'otp verify verification password reset confirm'],
  [/قاعد[ةه]\s*بيانات|جدول|جداول|تخزين|كاش/g, 'database db model schema migration table query cache redis'],
  [/واجهة|شاش[ةه]|شاشات|صفح[ةه]|صفحات|مكون/g, 'ui screen page view component frontend route layout'],
  [/خادم|سيرفر|باك\s*اند|مسار|مسارات|نقط[ةه]\s*نهاي[ةه]/g, 'server backend api router endpoint controller handler service'],
  [/خلفي[ةه]|مهام|طابور|مجدول|كرون/g, 'worker queue job task cron schedule background event'],
  [/خط[أا]|أخطاء|استثناء|سجل|لوج/g, 'error exception handler logger logging retry fallback'],
  [/اختبار|اختبارات|فحص/g, 'test spec e2e mock fixture'],
  [/إعداد|اعدادات|تهيئ[ةه]|بيئ[ةه]|نشر/g, 'config settings env deploy docker build'],
];

function expandBilingualQuery(q) {
  let extra = '';
  for (const [re, words] of UNIVERSAL_AR_SYNONYMS) {
    re.lastIndex = 0;
    if (re.test(q)) extra += ' ' + words;
  }
  return `${q} ${extra}`.trim();
}

function genericLayerRank(id) {
  if (id.startsWith('n:')) {
    const n = G.nodes.find((x) => 'n:' + x.id === id);
    const kindOrder = { ui: 1, feature: 3, service: 4, library: 5, worker: 6, data: 7, external: 8 };
    return kindOrder[n?.kind] || 5;
  }
  const p = id.toLowerCase();
  if (/(^f:|\/)(pages|views|screens|components|app|ui|web|frontend)\//.test(p)) {
    if (/\/(api|services|clients|http)\//.test(p)) return 3;
    if (/\/(hooks|stores|state|controllers)\//.test(p)) return 2;
    return 1;
  }
  if (id.startsWith('r:') || /\/(routes?|routers?|controllers?|endpoints?|handlers?)\//.test(p)) return 4;
  if (/\/(usecases?|domain|services?|workflows?|core)\//.test(p)) return 5;
  if (/\/(repositor|models?|db|data|prisma|migrations?|gateways?|adapters?|clients?)\//.test(p)) return 7;
  return 5;
}

function isTestGraphItem(id) {
  if (!id) return false;
  if (id.startsWith('n:')) {
    let n = G.nodes.find((x) => x.id === id.slice(2));
    while (n) { if (n.kind === 'test') return true; n = n.parent ? G.nodes.find((x) => x.id === n.parent) : null; }
    return false;
  }
  if (id.startsWith('f:')) {
    const p = id.slice(2);
    const f = G.files.find((x) => x.p === p);
    if (f && isTestGraphItem('n:' + f.n)) return true;
    return /(^|\/)(__tests__|tests?|specs?|e2e|cypress|playwright)\/|\.(test|spec)\.[a-z0-9]+$/i.test(p);
  }
  if (id.startsWith('s:')) return isTestGraphItem('f:' + id.slice(2).replace(/#\d+$/, ''));
  return false;
}

function isInternalDevOnlyItem(id) {
  if (!id) return false;
  if (isTestGraphItem(id)) return true;
  if (id.startsWith('n:')) {
    let n = G.nodes.find((x) => x.id === id.slice(2));
    while (n) { if (['test', 'script', 'infra', 'config'].includes(n.kind)) return true; n = n.parent ? G.nodes.find((x) => x.id === n.parent) : null; }
  }
  if (id.startsWith('f:')) {
    const f = G.files.find((x) => x.p === id.slice(2));
    if (f && isInternalDevOnlyItem('n:' + f.n)) return true;
  }
  return false;
}

function searchSourceMatches(terms, wantsTests = false) {
  const hits = [];
  const tokens = terms.toLowerCase().split(/\s+/).filter((t) => t.length >= 3 && !/^[0-9]+$/.test(t) && !/[\u0600-\u06FF]/.test(t)).slice(0, 8);
  if (!tokens.length) return hits;
  for (const f of G.files) {
    if (f.loc > 2500) continue;
    if (!wantsTests && isTestGraphItem('f:' + f.p)) continue;
    try {
      const src = fs.readFileSync(path.join(root, f.p), 'utf8').toLowerCase();
      let score = 0;
      for (const tok of tokens) if (src.includes(tok)) score++;
      if (score >= Math.min(2, tokens.length)) hits.push({ id: 'f:' + f.p, score });
    } catch {}
  }
  return hits.sort((a, b) => b.score - a.score).slice(0, 6).map((h) => core.q.brief(h.id)).filter(Boolean);
}

const AR_DOMAIN_TOPICS = [
  [/\b(login|signin|sign-in|oidc|oauth|sso|callback|keycloak)\b/i, 'تسجيل الدخول الموحّد والتحقق من هوية المستفيد'],
  [/\b(session|keepalive|idle|timeout|refresh)\b/i, 'إدارة الجلسة النشطة وتمديد صلاحيتها وتأمينها عند الخمول'],
  [/\b(logout|signout|sign-out|revoke)\b/i, 'تسجيل الخروج الآمن وإنهاء الجلسة ومسح البيانات المؤقتة'],
  [/\b(profile|personal|contact|account|beneficiary|user)\b/i, 'عرض وتحديث بيانات الحساب والملف الشخصي ومعلومات التواصل'],
  [/\b(password|credential|reset)\b/i, 'تغيير كلمة المرور والتحقق من سياسات واشتراطات الأمان'],
  [/\b(otp|verify|verification|code|mobile)\b/i, 'إرسال رموز التحقق المؤقتة وتأكيد ملكية الجوال أو البريد الإلكتروني'],
  [/\b(email|mail|notification|alert|sms)\b/i, 'إرسال الإشعارات والرسائل التنبيهية والتأكيدات للمستفيد'],
  [/\b(bill|bills|invoice|payment|sadad|checkout|charge|refund|fee)\b/i, 'استعراض الفواتير والرسوم وحالات السداد والمستحقات المالية'],
  [/\b(order|orders|cart|product|catalog)\b/i, 'إدارة الطلبات والمنتجات وسير إجراءات التنفيذ'],
  [/\b(request|requests|application|sla|service[-_]?request)\b/i, 'متابعة الطلبات الخدمية ومؤشرات الإنجاز وحالات المعالجة'],
  [/\b(violation|violations|objection|inspection|fine)\b/i, 'عرض المخالفات والتفاصيل المرفقة وحالات الاعتراض والسداد'],
  [/\b(inquiry|inquiries|complaint|crm|case|ticket|support)\b/i, 'إدارة الاستفسارات والبلاغات ومتابعة تذاكر الدعم'],
  [/\b(delegation|delegations|commercial|authorization|permission|role|rbac)\b/i, 'إدارة التفويضات والصلاحيات والسجلات المرتبطة بالحساب'],
  [/\b(home|dashboard|overview|summary|event)\b/i, 'عرض الملخص الرئيسي والمؤشرات والتنبيهات السريعة'],
  [/\b(cache|ttl|store|redis|memory)\b/i, 'حفظ النتائج المؤقتة لتسريع الاستجابة وتقليل الاعتماد المتكرر'],
  [/\b(error|exception|validation|sanitize)\b/i, 'فحص صحة المدخلات وتحويل الأعطال إلى رسائل واضحة وآمنة'],
  [/\b(gateway|connector|hub|integration|adapter|client|external)\b/i, 'التكامل والربط المباشر مع الأنظمة والمنصات الخارجية'],
];

function arabicLayerPrefix(item, isBusiness = false) {
  const id = item?.id || '';
  if (id.startsWith('r:')) {
    const r = G.routes[+id.slice(2)];
    const read = r?.m === 'GET';
    return isBusiness ? (read ? 'خدمة استعلام وعرض بيانات' : 'خدمة تنفيذ إجراء مباشر') : (read ? `نقطة استعلام (${r.m})` : `نقطة تنفيذ (${r?.m || 'API'})`);
  }
  if (id.startsWith('n:')) {
    const n = G.nodes.find((x) => x.id === id.slice(2));
    if (n?.kind === 'ui') return 'شاشة وتجربة المستفيد';
    if (n?.kind === 'external') return 'جهة / نظام خارجي متكامل';
    if (n?.kind === 'data') return isBusiness ? 'قواعد وتنظيم السجلات' : 'طبقة البيانات والنماذج';
    if (n?.kind === 'service' || n?.kind === 'worker') return isBusiness ? 'منظومة المعالجة الخلفية' : 'الخدمة الخادمية الأساسية';
    return isBusiness ? 'وحدة وظيفية للأعمال' : 'وحدة برمجية';
  }
  const rank = genericLayerRank(id);
  if (rank <= 2) return isBusiness ? 'واجهة تفاعل المستخدم' : 'مكوّن واجهة أمامية';
  if (rank === 3) return isBusiness ? 'حلقة الوصل بين الواجهة والنظام' : 'وسيط الاتصال بالخادم';
  if (rank === 4) return isBusiness ? 'بوابة استقبال طلبات المستفيد' : 'موجه الطلبات (Router)';
  if (rank === 5) return isBusiness ? 'محرك قواعد وسير العمل' : 'منطق وسير العمل (Usecase/Service)';
  return isBusiness ? 'تكامل مع مصادر البيانات والجهات المرتبطة' : 'طبقة البيانات والتكامل الخارجي';
}

function arabicExplanationFor(item, { isBusiness = false, info = null } = {}) {
  const rawDesc = String(item?.description || '').trim();
  const hasArabicDesc = /[\u0600-\u06FF]/.test(rawDesc);
  const layer = arabicLayerPrefix(item, isBusiness);

  if (hasArabicDesc) {
    const clean = rawDesc.split(/[.؟!\n]/)[0].trim();
    if (isBusiness) return `${layer}: ${clean}`;
    const techTail = info?.locRef ? ` (\`${info.locRef}\`${info.summary ? ` — ${info.summary}` : ''})` : '';
    return `${clean}${techTail}`;
  }

  const corpus = `${item?.name || ''} ${rawDesc} ${item?.path || ''} ${item?.id || ''}`;
  const matchedTopics = [];
  for (const [re, phrase] of AR_DOMAIN_TOPICS) {
    if (re.test(corpus) && !matchedTopics.includes(phrase)) matchedTopics.push(phrase);
    if (matchedTopics.length >= 2) break;
  }
  const coreMeaning = matchedTopics.length
    ? `تتولى ${matchedTopics.join('، مع ')}`
    : 'تنسّق معالجة الطلب وتبادل البيانات ضمن هذا المسار';

  if (isBusiness) {
    return `${layer} — ${coreMeaning}.`;
  }
  const techTail = info?.locRef ? ` (\`${info.locRef}\`${info.summary ? ` — ${info.summary}` : ''})` : '';
  return `${layer}: ${coreMeaning}${techTail}`;
}

function inspectCodeBody(item, isAr = false) {
  if (!item || G.meta?.blueprint) return null;
  try {
    let relFile = '', startL = 1, endL = 55, symbolName = '';
    if (item.id.startsWith('r:')) {
      const r = G.routes[+item.id.slice(2)];
      if (!r?.f) return null;
      relFile = r.f;
      startL = Math.max(1, r.l || 1);
      endL = startL + 60;
      symbolName = r.h || `${r.m} ${r.p}`;
    } else if (item.id.startsWith('s:')) {
      const m = /^s:(.*)#(\d+)$/.exec(item.id);
      const f = m && G.files.find((x) => x.p === m[1]);
      const sym = f?.s?.[+m[2]];
      if (!sym) return null;
      relFile = f.p;
      startL = Math.max(1, sym[2] || 1);
      endL = startL + 55;
      symbolName = sym[0];
    } else if (item.id.startsWith('f:')) {
      relFile = item.id.slice(2);
      const f = G.files.find((x) => x.p === relFile);
      const firstSym = f?.s?.[0];
      startL = Math.max(1, firstSym?.[2] || 1);
      endL = startL + 55;
      symbolName = firstSym?.[0] || '';
    } else {
      return null;
    }

    const snip = safeReadSnippet(root, relFile, startL, endL);
    if (snip.error || !snip.snippet) return { locRef: `${relFile}:L${startL}`, summary: '' };
    const rawLines = snip.snippet.split('\n');
    // Trim body at next top-level definition after the first 3 lines so we stay inside one function/route
    let bodyEndIdx = rawLines.length;
    for (let i = 3; i < rawLines.length; i++) {
      const codeOnly = rawLines[i].replace(/^L\d+:\s*/, '');
      if (/^(?:export\s+)?(?:async\s+)?(?:def\s+\w+|function\s+\w+|class\s+\w+)|^@(?:app|router|bp)\./.test(codeOnly)) {
        bodyEndIdx = i;
        break;
      }
    }
    const bodyText = rawLines.slice(0, bodyEndIdx).map((l) => l.replace(/^L\d+:\s*/, '')).join('\n');
    const actualEndL = startL + bodyEndIdx - 1;
    const locRef = actualEndL > startL ? `${relFile}:L${startL}-${actualEndL}` : `${relFile}:L${startL}`;

    const facts = [];
    const guard = /\b(Depends\(\s*[\w.]+\s*\)|Security\(\s*[\w.]+\s*\)|@(?:login_required|UseGuards\([^)]+\)|Authorize\b)|(?:require|verify|check|ensure|validate)_?[A-Za-z0-9_]*(?:Auth|Token|Session|User|Role|Permission|Signature)\w*|getServerSession|jwt\.verify|cookies\.get\([^)]+\))/i.exec(bodyText);
    if (guard) facts.push(isAr ? `يتحقق عبر \`${guard[1].trim()}\`` : `guards via \`${guard[1].trim()}\``);

    const statusMatch = /\b(?:status(?:_code|Code)?\s*[:=(]\s*(40[01349]|422|50\d|30[1278])\b|HTTPException\s*\(\s*(?:status_code\s*=\s*)?(40[01349]|422)|\babort\s*\(\s*(40[0134])\b)/.exec(bodyText);
    if (statusMatch) {
      const code = statusMatch[1] || statusMatch[2] || statusMatch[3];
      facts.push(isAr ? `يرفض عند الفشل بكود HTTP ${code}` : `rejects invalid requests with HTTP ${code}`);
    }

    const callMatches = [...bodyText.matchAll(/\b(?:await\s+)?([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)?)\s*\(/g)]
      .map((m) => m[1])
      .filter((fn) => !/^(if|for|while|switch|catch|return|Promise|JSON|Object|Array|String|Number|Math|console|len|str|int|dict|list|set|super|Depends|Security|HTTPException|Error)$/.test(fn.split('.')[0]));
    const topCalls = [...new Set(callMatches)].filter((c) => c !== symbolName).slice(0, 2);
    if (topCalls.length) {
      facts.push(isAr ? `يستدعي \`${topCalls.join('()`, `')}()\`` : `calls \`${topCalls.join('()`, `')}()\``);
    }

    return {
      locRef,
      symbolName,
      summary: facts.join(isAr ? '، ' : ', '),
    };
  } catch {
    return null;
  }
}

/** Expand hit items into a connected execution chain using real graph edges (`core.q.path`). */
function buildConnectedTrace(chosen, { wantsTests = false, isBusiness = false } = {}) {
  const keep = (b) => b && b.id && (wantsTests || !isTestGraphItem(b.id)) && (!isBusiness || (!b.id.startsWith('s:') && !isInternalDevOnlyItem(b.id)));
  const ordered = [...chosen].filter(keep).sort((a, b) => genericLayerRank(a.id) - genericLayerRank(b.id));
  if (ordered.length < 2) return ordered;
  const result = [];
  const seen = new Set();
  const push = (b) => { if (keep(b) && !seen.has(b.id)) { seen.add(b.id); result.push(b); } };

  push(ordered[0]);
  for (let i = 1; i < ordered.length && result.length < 9; i++) {
    const prev = result[result.length - 1];
    const next = ordered[i];
    try {
      const trace = core.q.path(prev.id, next.id);
      if (trace?.found && trace.hops?.length <= 4) {
        for (const hop of trace.hops) {
          push(hop.from);
          if (hop.endpoints?.[0]) {
            const epId = hop.endpoints[0].split(' ')[0];
            push(core.q.brief(epId));
          }
          push(hop.to);
        }
        continue;
      }
    } catch {}
    push(next);
  }
  return result.slice(0, 8);
}

function localGraphAnswer(body, send, fallbackNotice = '') {
  const rawQ = String(body.question || '').split('\n\nFocus on these map items:')[0].trim();
  const isAr = body.lang === 'ar' || /[\u0600-\u06FF]/.test(rawQ) || (!body.lang && G.meta?.language === 'ar');
  const isBusiness = body.audience === 'business';
  const wantsTests = /\b(tests?|specs?|e2e|pytest|vitest|jest|mock)\b|اختبار|اختبارات|فحص/i.test(rawQ);

  send('progress', {
    text: isAr
      ? (isBusiness ? 'تحليل رحلة المستفيد والوحدات الوظيفية للأعمال...' : 'تحليل خريطة المعمارية وقراءة مقتطفات الدوال الفعلية...')
      : (isBusiness ? 'Mapping business capabilities and user journey...' : 'Analyzing architecture graph and reading function bodies...'),
  });

  const expanded = expandBilingualQuery(rawQ);
  const rawHits = [];
  const seen = new Set();
  const pushHit = (h) => {
    if (!h || seen.has(h.id)) return;
    if (!wantsTests && isTestGraphItem(h.id)) return;
    if (isBusiness && (h.id.startsWith('s:') || isInternalDevOnlyItem(h.id))) return;
    seen.add(h.id);
    rawHits.push(h);
  };
  if (isBusiness) {
    for (const mh of core.q.find(expanded, 'module', 8)) pushHit(mh);
    for (const fh of core.q.find(expanded, undefined, 10)) {
      if (fh.id.startsWith('f:')) {
        const gf = (G.files || []).find((x) => x.p === fh.id.slice(2));
        if (gf?.n) pushHit(core.q.brief('n:' + gf.n));
      } else if (fh.id.startsWith('n:')) {
        pushHit(fh);
      }
      if (rawHits.length < 4) pushHit(fh);
    }
  } else {
    for (const h of core.q.find(expanded, undefined, 14)) pushHit(h);
    for (const sh of searchSourceMatches(expanded, wantsTests)) {
      if (rawHits.length < 12) pushHit(sh);
    }
  }

  const baseHits = rawHits.length
    ? rawHits.slice(0, 8)
    : G.nodes
        .filter((n) => !n.parent && n.id !== 'unassigned' && (!isBusiness || !['test', 'script', 'infra', 'config'].includes(n.kind)))
        .slice(0, 6)
        .map((n) => core.q.brief('n:' + n.id))
        .filter(Boolean);

  const traceChain = buildConnectedTrace(baseHits, { wantsTests, isBusiness });
  const allRelevant = [...traceChain];
  for (const h of baseHits) if (!allRelevant.some((x) => x.id === h.id) && allRelevant.length < 12) allRelevant.push(h);

  const codeFacts = new Map();
  if (!isBusiness) {
    for (const it of allRelevant.slice(0, 7)) {
      const info = inspectCodeBody(it, isAr);
      if (info) codeFacts.set(it.id, info);
    }
  }

  const items = allRelevant.slice(0, 12).map((item) => {
    const info = codeFacts.get(item.id);
    if (isAr) {
      return { id: item.id, note: arabicExplanationFor(item, { isBusiness, info }).replace(/`/g, '').slice(0, 120) };
    }
    const baseDesc = (item.description || (!isBusiness ? item.path : '') || item.name || '').split('.')[0].slice(0, 85);
    const note = isBusiness
      ? (baseDesc || item.name)
      : info?.summary
      ? `${baseDesc ? baseDesc + ' — ' : ''}${info.summary} (${info.locRef})`
      : info?.locRef && baseDesc
      ? `${baseDesc} (${info.locRef})`
      : baseDesc || item.name;
    return { id: item.id, note: note.slice(0, 120) };
  });

  const steps = traceChain.length >= 2 ? traceChain.slice(0, 8).map((it) => {
    const info = codeFacts.get(it.id);
    if (isAr) {
      return { id: it.id, note: arabicExplanationFor(it, { isBusiness, info }).replace(/`/g, '').slice(0, 130) };
    }
    const desc = (it.description || it.name || '').split('.')[0].slice(0, 75);
    const detail = !isBusiness && info?.summary ? `${info.summary} [${info.locRef}]` : (!isBusiness && info?.locRef ? `[${info.locRef}]` : '');
    return { id: it.id, note: `${desc}${detail ? ' · ' + detail : ''}`.slice(0, 130) };
  }) : [];

  if (body.mode === 'flow') {
    const flowSteps = steps.length >= 2 ? steps : items.slice(0, 4);
    return {
      title: rawQ.slice(0, 48) || (isAr ? (isBusiness ? 'رحلة العمل عبر المنصة' : 'مسار تنفيذي في النظام') : 'System workflow'),
      description: isAr
        ? (isBusiness ? `رحلة المستفيد وسير العمل عبر ${flowSteps.length} مراحل وظيفية مترابطة.` : `تتبّع المسار عبر ${flowSteps.length} محطات مترابطة بأرقام الأسطر الفعلية.`)
        : (isBusiness ? `Business journey across ${flowSteps.length} connected stages.` : `End-to-end trace across ${flowSteps.length} connected parts with exact source lines.`),
      steps: flowSteps,
    };
  }

  const topTitle = isAr
    ? (/[\u0600-\u06FF]/.test(rawQ) && rawQ.length <= 52 ? rawQ : (isBusiness ? 'ملخص سير العمل ورحلة المستفيد' : 'تحليل المسار المعماري في المنصة'))
    : (rawQ.length <= 48 ? rawQ : (traceChain[0]?.name || 'Architecture overview'));

  const bulletLines = (traceChain.length ? traceChain : allRelevant).slice(0, 6).map((it, idx) => {
    const info = codeFacts.get(it.id);
    if (isAr) {
      return `${idx + 1}. [[${it.id}]] — ${arabicExplanationFor(it, { isBusiness, info })}`;
    }
    const desc = it.description || (!isBusiness ? it.path : '') || '';
    const codeBadge = !isBusiness && info?.locRef ? ` (\`${info.locRef}\`${info.summary ? ` — ${info.summary}` : ''})` : '';
    return `${idx + 1}. [[${it.id}]] — ${desc}${codeBadge}`;
  });

  const noticeLine = fallbackNotice
    ? (isAr
        ? (isBusiness ? '' : `> أُجيب تلقائياً عبر **المحرك المحلي المدمج** (${fallbackNotice}).\n\n`)
        : (isBusiness ? '' : `> Answered via **Local Engine** fallback (${fallbackNotice}).\n\n`))
    : '';

  const intro = isAr
    ? (isBusiness
        ? `في هذه المنصة، تسير هذه الرحلة الوظيفية وتتكامل خطواتها لخدمة المستفيد على النحو التالي:`
        : `${noticeLine}يتوزع تنفيذ هذا المسار المعماري عبر المكونات البرمجية المترابطة التالية بالترتيب:`)
    : (isBusiness
        ? `From a business perspective, **${G.project.name}** handles this journey across the following capabilities:`
        : `${noticeLine}In **${G.project.name}**, this works across the following connected components in execution order:`);

  const topSystems = G.nodes.filter((n) => !n.parent && n.id !== 'unassigned' && !['test', 'script', 'infra', 'config'].includes(n.kind)).slice(0, 2);
  const followups = isAr
    ? (isBusiness
        ? [
            'ما هي الخدمات الرئيسية التي تقدمها المنصة للمستفيدين؟',
            'ما هي الأنظمة والجهات الخارجية المتكاملة مع المنصة؟',
            'كيف تتم رحلة التحقق من هوية المستفيد وحماية حسابه؟',
          ]
        : [
            'كيف تتم حماية المسارات والتحقق من الجلسات والصلاحيات؟',
            'كيف تتكامل الواجهة الأمامية مع خدمات الخادم الخلفي؟',
            'ما هي البوابات الخارجية وآلية معالجة الأخطاء في النظام؟',
          ])
    : (isBusiness
        ? [
            'What are the main user journeys supported by this platform?',
            'Which outside services and partners does the platform rely on?',
            'How does the platform protect user accounts and data?',
          ]
        : [
            topSystems[0] ? `How does ${topSystems[0].label} connect to the rest of the system?` : 'What are the main subsystems in this project?',
            G.routes?.length ? 'How do endpoints verify authentication and permissions?' : 'How do the core modules depend on each other?',
            topSystems[1] ? `What happens inside ${topSystems[1].label}?` : 'What are the main end-to-end data flows?',
          ]);

  return {
    title: topTitle,
    answer: `${intro}\n\n${bulletLines.join('\n')}`,
    items,
    steps,
    followups,
  };
}

function ask(req, res, body) {
  res.writeHead(200, { 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-store', Connection: 'keep-alive' });
  const send = (event, data) => { if (!res.writableEnded) res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`); };
  const chosenId = normEngine(body.engine) || engine;
  if (body.mode === 'change') return changePlan(res, send, body, chosenId);
  if (!cli || chosenId === 'local') {
    try { send('answer', localGraphAnswer(body, send)); }
    catch (e) { send('failure', { code: 'cli_error', message: String(e.message || e) }); }
    return res.end();
  }
  runAgent(res, send, body, chosenId)
    .then((a) => send('answer', a), (e) => {
      if (e === CLOSED) return;
      const code = failCode(String(e.message || e));
      // If an auto-detected CLI isn't signed in, switch default engine to 'local' so future asks are instant
      if (code === 'not_logged_in' && !asked && chosenId === engine && engine !== 'local') {
        engine = 'local';
        cli = ENGINES.local.find();
        refreshVersion();
        try { load(); } catch {}
      }
      if (!body.noFallback && (code === 'not_logged_in' || code === 'cli_error' || code === 'rate_limited')) {
        try {
          const shortReason = code === 'not_logged_in'
            ? (body.lang === 'ar' ? `${ENGINES[chosenId]?.label || chosenId} غير مسجل الدخول` : `${ENGINES[chosenId]?.label || chosenId} not signed in`)
            : `${ENGINES[chosenId]?.label || chosenId}: ${String(e.message || e).slice(0, 70)}`;
          send('answer', localGraphAnswer(body, send, shortReason));
          return;
        } catch {}
      }
      send('failure', { code, message: String(e.message || e) });
    })
    .finally(() => res.end());
}

// ---------- changing a blueprint from the map ----------
const historyDir = path.join(here, '.cache', 'history');
const PLAN_FILES = ['plan.json', 'architecture.json', 'recent-work.json'];
let changing = false;
function snapshot() {
  const dir = path.join(historyDir, Date.now().toString(36));
  fs.mkdirSync(dir, { recursive: true });
  for (const f of PLAN_FILES) if (fs.existsSync(path.join(here, f))) fs.copyFileSync(path.join(here, f), path.join(dir, f));
  for (const old of fs.readdirSync(historyDir).sort().slice(0, -20)) fs.rmSync(path.join(historyDir, old), { recursive: true, force: true });
  return dir;
}
function restore(dir) {
  for (const f of PLAN_FILES) { const from = path.join(dir, f), to = path.join(here, f); if (fs.existsSync(from)) fs.copyFileSync(from, to); else fs.rmSync(to, { force: true }); }
}
function skillScript(name, ...args) {
  let dir;
  try { dir = readJson(path.join(here, '.cache', 'skill.json')).dir; } catch {}
  if (!dir || !fs.existsSync(path.join(dir, 'scripts', name))) throw new Error('This map’s server can’t find the Floorplan scripts. Ask your AI assistant to update the floorplan once, then try again.');
  try { return execFileSync(process.execPath, [path.join(dir, 'scripts', name), root, ...args], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], windowsHide: true, timeout: 120000 }); }
  catch (e) { throw Object.assign(new Error(String(e.stdout || '') + String(e.stderr || '') || e.message), { checks: true }); }
}
function problems(text) {
  const out = [];
  let inErrors = false;
  for (const l of String(text || '').split('\n')) {
    if (/^✗/.test(l)) inErrors = true;
    else if (/^\S/.test(l)) inErrors = false;
    else if (inErrors && /^\s+- /.test(l)) out.push(l.trim().slice(2));
  }
  return out;
}
function applyChange(data, request, lastTry) {
  const parse = (name, text) => { try { const v = typeof text === 'object' ? text : JSON.parse(String(text || '')); return v && typeof v === 'object' && !Array.isArray(v) ? v : null; } catch { return null; } };
  const plan = parse('plan', data.plan), arch = parse('architecture', data.architecture);
  if (!plan || !arch) return { errors: [`${!plan ? 'plan' : 'architecture'} isn't a complete JSON object`] };
  const snap = snapshot();
  const write = (f, v) => fs.writeFileSync(path.join(here, f), JSON.stringify(v, null, 2) + '\n');
  try {
    write('plan.json', plan);
    write('architecture.json', arch);
    const items = (Array.isArray(data.changes) ? data.changes : []).filter((c) => c && typeof c.ref === 'string').map((c) => ({ ref: c.ref, change: c.change === 'changed' ? 'changed' : 'new', note: String(c.note || '') }));
    const plain = String(data.summary || '').split(/\n\s*\n/)[0].replace(/\*\*|__|`/g, '').replace(/\s+/g, ' ').trim();
    write('recent-work.json', { updatedAt: new Date().toISOString(), tasks: [{ title: String(data.title || 'Changed the plan').slice(0, 80), request, summary: plain, status: 'planned, not built', items }] });
    skillScript('plan.mjs');
    const check = skillScript('build.mjs', '--check');
    const unassigned = +(/(\d+) unassigned/.exec(check)?.[1] || 0);
    if (unassigned && !lastTry) throw Object.assign(new Error(''), { checks: true, list: [`${unassigned} planned file(s) fall under no node's paths in architecture.json (add or widen globs)`] });
    skillScript('build.mjs', '--no-agent-notes');
    return { ok: true, undo: path.basename(snap) };
  } catch (e) {
    restore(snap);
    fs.rmSync(snap, { recursive: true, force: true });
    try { skillScript('plan.mjs'); } catch {}
    if (!e.checks) throw e;
    return { errors: e.list || problems(e.message).slice(0, 12).concat(problems(e.message).length ? [] : [e.message.trim().split('\n').pop()]) };
  }
}
async function changePlan(res, send, body, chosenId = engine) {
  const request = String(body.question || '').slice(0, 4000);
  if (!G.meta?.blueprint || !ENGINES[chosenId]?.structured) {
    send('failure', { code: 'cli_error', message: G.meta?.blueprint ? `${ENGINES[chosenId]?.name || chosenId} can't change a plan from the map. Switch to a structured AI engine.` : 'Only a blueprint can be changed from the map.' });
    return res.end();
  }
  if (!MODES.change) MODES.change = { instructions: core.floorplanChangeInstructions(G), httpInstructions: core.floorplanChangeInstructions(G), schema: core.FLOORPLAN_CHANGE_SCHEMA, file: path.join(here, '.cache', 'change-schema.json') };
  if (changing) { send('failure', { code: 'busy', message: 'Another change to this plan is still being made. Try again when it’s done.' }); return res.end(); }
  changing = true;
  let session, errors = null;
  try {
    for (let attempt = 0; attempt < 2; attempt++) {
      const question = errors
        ? `Your updated plan didn't pass the checks, so nothing was saved:\n${errors.map((e) => `- ${e}`).join('\n')}\n\nFix these and reply again with the complete files. The request was: ${request}`
        : request;
      const data = await runAgent(res, send, { question, session, mode: 'change' }, chosenId);
      session = data.session || session;
      send('progress', { text: 'Checking the updated plan' });
      const r = applyChange(data, request, attempt === 1);
      if (r.ok) {
        console.log(`plan changed: ${data.title || request.slice(0, 60)}`);
        send('answer', { title: String(data.title || ''), summary: String(data.summary || ''), changes: (data.changes || []).length, followups: Array.isArray(data.followups) ? data.followups.map(String).slice(0, 3) : [], undo: r.undo });
        return;
      }
      errors = r.errors;
      send('progress', { text: `Fixing ${errors.length === 1 ? 'a problem' : `${errors.length} problems`} the checks found` });
    }
    send('failure', { code: 'change_invalid', message: `The updated plan didn't pass the checks, so nothing changed:\n${errors.slice(0, 6).map((e) => `- ${e}`).join('\n')}` });
  } catch (e) {
    if (e !== CLOSED) send('failure', { code: failCode(String(e.message || e)), message: String(e.message || e) });
  } finally { changing = false; res.end(); }
}

function undoChange() {
  const all = fs.existsSync(historyDir) ? fs.readdirSync(historyDir).sort() : [];
  if (!all.length) return { ok: false, error: 'Nothing to undo.' };
  const dir = path.join(historyDir, all[all.length - 1]);
  restore(dir);
  try { skillScript('plan.mjs'); skillScript('build.mjs', '--no-agent-notes'); } catch (e) {
    console.error(`✗ Undo couldn't redraw the plan: ${e.message || e}`);
    return { ok: false, error: 'Couldn’t redraw the previous plan. The details are in the map server’s output.' };
  }
  fs.rmSync(dir, { recursive: true, force: true });
  return { ok: true, left: all.length - 1 };
}

// ---------- http ----------
const server = http.createServer((req, res) => {
  if (![`127.0.0.1:${port}`, `localhost:${port}`].includes(String(req.headers.host || '').toLowerCase())) { res.writeHead(403); return res.end('unknown host'); }
  const url = new URL(req.url, `http://${req.headers.host}`);
  const sameOrigin = !req.headers.origin || req.headers.origin === `http://${req.headers.host}`;
  if (url.pathname.startsWith('/api/')) {
    const givenToken = req.headers['x-floorplan-token'] || (url.pathname === '/api/events' ? url.searchParams.get('token') : null);
    if (!sameOrigin || givenToken !== token) { res.writeHead(403); return res.end(); }

    if (req.method === 'GET' && url.pathname === '/api/events') {
      res.writeHead(200, { 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-store', Connection: 'keep-alive' });
      res.write('retry: 1000\n\n');
      tabs.add(res);
      req.on('close', () => { tabs.delete(res); lastTab = Date.now(); });
      return;
    }
    if (req.method === 'GET' && url.pathname === '/api/status') {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      return res.end(JSON.stringify({ tabs: tabs.size, pid: process.pid, hash: selfHash, root, editor, autoRefresh }));
    }
    if (req.method === 'GET' && url.pathname === '/api/health') {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      return res.end(JSON.stringify({ cli: !!cli, engine, engineLabel: ENGINES[engine]?.label || engine, protocol: activeProtocol(), want, version, path: cli?.path || null }));
    }
    if (url.pathname === '/api/engines') {
      if (req.method === 'GET') {
        listAvailableEngines().then((engines) => {
          res.writeHead(200, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ active: engine, model: model || cli?.provider?.model || null, engines }));
        }).catch((e) => {
          res.writeHead(500, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: e.message }));
        });
        return;
      }
      if (req.method === 'POST') {
        let raw = '';
        req.on('data', (d) => { raw += d; if (raw.length > 5000) req.destroy(); });
        req.on('end', async () => {
          let body = {}; try { body = JSON.parse(raw); } catch {}
          await getOllamaStatus();
          const nextId = normEngine(body.engine);
          if (!nextId) { res.writeHead(400, { 'Content-Type': 'application/json' }); return res.end(JSON.stringify({ ok: false, error: 'Unknown engine id' })); }
          if (typeof body.model === 'string') model = body.model.trim();
          const found = ENGINES[nextId].find();
          if (!found) { res.writeHead(400, { 'Content-Type': 'application/json' }); return res.end(JSON.stringify({ ok: false, error: `${ENGINES[nextId].label} is not configured or installed on this machine.` })); }
          engine = nextId;
          cli = found;
          refreshVersion();
          try { load(); } catch {}
          const engines = await listAvailableEngines();
          res.writeHead(200, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ ok: true, active: engine, engineLabel: cli?.provider?.label || ENGINES[engine].label, protocol: activeProtocol(), change: !!ENGINES[engine].structured, model: model || cli?.provider?.model || null, engines }));
        });
        return;
      }
    }
    if (url.pathname === '/api/flows') {
      if (req.method === 'GET') { res.writeHead(200, { 'Content-Type': 'application/json' }); return res.end(JSON.stringify({ flows: readFlows() })); }
      if (req.method === 'POST' || req.method === 'DELETE') {
        let raw = '';
        req.on('data', (d) => { raw += d; if (raw.length > 50000) req.destroy(); });
        req.on('end', () => {
          let body = {}; try { body = JSON.parse(raw); } catch {}
          const flows = readFlows().filter((x) => x.id !== body.id && x.id !== body.flow?.id);
          if (req.method === 'POST' && body.flow?.id && Array.isArray(body.flow.steps)) flows.push({ ...body.flow, createdAt: new Date().toISOString() });
          fs.writeFileSync(flowsFile, JSON.stringify({ flows }, null, 2) + '\n');
          res.writeHead(200, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ flows }));
        });
        return;
      }
    }
    if (url.pathname === '/api/health/dismissed') {
      if (req.method === 'GET') { res.writeHead(200, { 'Content-Type': 'application/json' }); return res.end(JSON.stringify({ dismissed: readDismissed() })); }
      if (req.method === 'POST' || req.method === 'DELETE') {
        let raw = '';
        req.on('data', (d) => { raw += d; if (raw.length > 100000) req.destroy(); });
        req.on('end', () => {
          let body = {}; try { body = JSON.parse(raw); } catch {}
          if (typeof body.id !== 'string') { res.writeHead(400); return res.end(); }
          const dismissed = readDismissed().filter((x) => x.id !== body.id);
          if (req.method === 'POST') dismissed.push(cleanDismissal(body));
          fs.writeFileSync(dismissedFile, JSON.stringify({ dismissed }, null, 2) + '\n');
          res.writeHead(200, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ dismissed }));
        });
        return;
      }
    }
    if (url.pathname.startsWith('/api/cloud/')) {
      const json = (data) => { res.writeHead(200, { 'Content-Type': 'application/json' }); res.end(JSON.stringify(data)); };
      if (req.method === 'GET' && url.pathname === '/api/cloud/prompt') return json({ show: cloudPrompt() });
      if (req.method === 'POST') {
        let raw = '';
        req.on('data', (d) => { raw += d; if (raw.length > 2000) req.destroy(); });
        req.on('end', async () => {
          let body = {}; try { body = JSON.parse(raw); } catch {}
          if (url.pathname === '/api/cloud/claude-email') return json({ email: claudeEmail() });
          if (url.pathname === '/api/cloud/join') return json(await joinWaitlist(body));
          if (url.pathname === '/api/cloud/dismiss') {
            saveCloud(body.forever ? { status: 'never' } : { status: 'later', until: new Date(Date.now() + 14 * 864e5).toISOString() });
            return json({ ok: true });
          }
          res.writeHead(404); res.end();
        });
        return;
      }
    }
    if (req.method === 'POST' && url.pathname === '/api/plan/undo') {
      const r = changing ? { ok: false, error: 'A change is still being made.' } : undoChange();
      res.writeHead(200, { 'Content-Type': 'application/json' }); return res.end(JSON.stringify(r));
    }
    if (req.method === 'POST' && url.pathname === '/api/cancel') { for (const c of running.values()) c.kill(); res.writeHead(204); return res.end(); }
    if (req.method === 'POST' && url.pathname === '/api/export') {
      let raw = '';
      req.on('data', (d) => { raw += d; if (raw.length > 500000) req.destroy(); });
      req.on('end', () => {
        let body = {}; try { body = JSON.parse(raw); } catch {}
        try {
          const x = exportMap(Array.isArray(body.include) ? body.include.map(String) : EXPORT_DEFAULT, cleanFlows(body.flows));
          res.writeHead(200, { 'Content-Type': TYPES['.html'], 'Content-Disposition': `attachment; filename="${x.name}"`, 'Cache-Control': 'no-store' });
          res.end(x.html);
        } catch (e) {
          console.error(`✗ Couldn't export the map: ${e.message}`);
          res.writeHead(500, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: e.plain ? e.message : 'The map’s server couldn’t export it. The details are in its output.' }));
        }
      });
      return;
    }
    if (req.method === 'POST' && url.pathname === '/api/ask') {
      let raw = '';
      req.on('data', (d) => { raw += d; if (raw.length > 20000) req.destroy(); });
      req.on('end', () => { let body = {}; try { body = JSON.parse(raw); } catch {} ask(req, res, body); });
      return;
    }
    res.writeHead(404); return res.end();
  }
  if (url.pathname === '/' || url.pathname === '/index.html') { res.writeHead(200, { 'Content-Type': TYPES['.html'], 'Cache-Control': 'no-store' }); return res.end(page); }
  let file;
  try { file = path.join(here, decodeURIComponent(url.pathname)); } catch { res.writeHead(400); return res.end('bad address'); }
  if (!file.startsWith(here + path.sep) || !fs.existsSync(file) || !fs.statSync(file).isFile()) { res.writeHead(404); return res.end('not found'); }
  res.writeHead(200, { 'Content-Type': TYPES[path.extname(file)] || 'application/octet-stream' });
  fs.createReadStream(file).pipe(res);
});

let port = wantPort;
server.on('error', (e) => {
  if (e.code === 'EADDRINUSE' && port < wantPort + 20) { port++; server.listen(port, '127.0.0.1'); return; }
  console.error(`✗ Couldn't start the map server: ${e.message}`);
  process.exit(1);
});
server.listen(port, '127.0.0.1');
server.on('listening', () => {
  const u = `http://127.0.0.1:${port}`;
  try {
    fs.mkdirSync(path.dirname(stateFile), { recursive: true });
    fs.writeFileSync(stateFile, JSON.stringify({ pid: process.pid, port, url: u, token, hash: selfHash, startedAt: new Date().toISOString() }, null, 2));
  } catch {}
  const forget = () => { try { if (readState()?.pid === process.pid) fs.unlinkSync(stateFile); } catch {} };
  process.on('exit', forget);
  for (const sig of ['SIGINT', 'SIGTERM', 'SIGHUP']) process.on(sig, () => process.exit(0));
  console.log(`Floorplan: ${u}`);
  console.log(`asking via ${ENGINES[engine].name}${version ? ` (${version})` : ''} [${activeProtocol()}]`);
});
